// Today's sky for one place, midnight to midnight: the background is the
// sky's color through the day (night, astronomical, nautical and civil
// twilight, golden hour, day), the sun's path is drawn over it with the
// horizon across, the moon's path beside it, and underneath how long the day
// is, when the light comes and goes, and how the moon is. All of it is worked
// out on the frame from the place's latitude and longitude.
import { WEEKDAYS, MONTHS, timeText, two } from './time'
import { sunAltitude, moonAltitude, moonIllumination, moonPhaseName, moonPath } from './sun'

const STEP = 5 * 60000

// The sky's color by the sun's altitude.
const SKY: [number, string][] = [
  [-18, '#0a1024'],
  [-12, '#141d43'],
  [-6, '#26356e'],
  [-2, '#57508a'],
  [0, '#b56f72'],
  [3, '#e0975e'],
  [6, '#e9b56f'],
  [10, '#7fa6d6'],
  [25, '#5a8fd0'],
]

function hex(value: number) {
  const text = Math.max(0, Math.min(255, Math.round(value))).toString(16)
  return text.length < 2 ? '0' + text : text
}

function mix(a: string, b: string, t: number) {
  const pa = parseInt(a.substring(1), 16)
  const pb = parseInt(b.substring(1), 16)
  return '#' + hex(((pa >> 16) & 255) * (1 - t) + ((pb >> 16) & 255) * t) +
    hex(((pa >> 8) & 255) * (1 - t) + ((pb >> 8) & 255) * t) + hex((pa & 255) * (1 - t) + (pb & 255) * t)
}

function skyAt(altitude: number) {
  if (altitude <= SKY[0][0]) return SKY[0][1]
  for (let i = 1; i < SKY.length; i++) {
    if (altitude <= SKY[i][0]) return mix(SKY[i - 1][1], SKY[i][1], (altitude - SKY[i - 1][0]) / (SKY[i][0] - SKY[i - 1][0]))
  }
  return SKY[SKY.length - 1][1]
}

// When a series of altitudes crosses a level, rising or setting.
function crossings(start: number, values: number[], level: number) {
  const found: { at: number; rising: boolean }[] = []
  for (let i = 1; i < values.length; i++) {
    const a = values[i - 1] - level
    const b = values[i] - level
    if ((a < 0 && b >= 0) || (a >= 0 && b < 0)) {
      found.push({ at: start + (i - 1 + a / (a - b)) * STEP, rising: b >= 0 })
    }
  }
  return found
}

function series(start: number, steps: number, altitude: (ms: number) => number) {
  const values = []
  for (let i = 0; i <= steps; i++) values.push(altitude(start + i * STEP))
  return values
}

function lengthText(ms: number) {
  const minutes = Math.round(ms / 60000)
  return `${Math.floor(minutes / 60)}h ${two(minutes % 60)}m`
}

function changeText(ms: number) {
  const seconds = Math.round(Math.abs(ms) / 1000)
  if (seconds < 5) return 'the same as yesterday'
  const text = (seconds >= 60 ? Math.floor(seconds / 60) + 'm ' : '') + (seconds % 60) + 's'
  return `${ms > 0 ? '+' : '−'}${text} on yesterday`
}

// The next moment the moon reaches a phase (0 new, 0.5 full), within a month.
function nextPhase(from: number, target: number) {
  let previous = moonIllumination(from).phase
  for (let t = from + 3 * 3600000; t < from + 31 * 86400000; t += 3 * 3600000) {
    const phase = moonIllumination(t).phase
    const crossed = target === 0 ? phase < previous - 0.5 : previous < target && phase >= target
    if (crossed) return t
    previous = phase
  }
  return null
}

// The colors. A panel with no color (1-bit, or e-paper's greys) dithers the
// sky's gradient and its pale lines to dots: there the page is white, the
// night hatched and every line and word black. Color e-paper has the night
// a solid blue and its other inks for the sun: a blend of inks is confetti,
// and so is a thin colored line, so a line over the night has the page under
// it.
type Look = {
  sky: boolean; page: string; ink: string; soft: string; label: string; rule: string; axis: string; hatch: string; night: string; horizon: string
  sunPath: string; moonPath: string; sun: string; sunRing: string; moonDark: string; moonLit: string; moonRing: string
  mark: string; markText: string; noonText: string; now: string
}
const COLOR: Look = {
  sky: true, page: '#0a1024', ink: '#ffffff', soft: '#aab5d4', label: '#8d9bc0', rule: '#2a3558', axis: '#8d9bc0', hatch: '', night: '', horizon: '#ffffff',
  sunPath: '#ffd36b', moonPath: '#d6def0', sun: '#ffdf85', sunRing: '#fff3cc', moonDark: '#2b3350', moonLit: '#eef1f8', moonRing: '#2b3350',
  mark: '#ffd36b', markText: '#ffffff', noonText: '#ffffff', now: '#ffffff',
}
const HIGH: Look = {
  sky: false, page: '#ffffff', ink: '#000000', soft: '#000000', label: '#000000', rule: '#000000', axis: '#000000', hatch: '#000000', night: '', horizon: '#000000',
  sunPath: '#000000', moonPath: '#000000', sun: '#ffffff', sunRing: '#000000', moonDark: '#000000', moonLit: '#ffffff', moonRing: '#000000',
  mark: '#000000', markText: '#000000', noonText: '#000000', now: '#000000',
}
const INKS: Look = { ...HIGH, hatch: '', night: '#0000ff', sunPath: '#800000', sun: '#ffff00', mark: '#800000' }

function lookOf(app: FrameOSApp): Look {
  const mode = app.state.contrast || 'auto'
  if (mode === 'high' || (mode === 'auto' && app.frame.color === false)) return HIGH
  if (mode === 'auto' && app.frame.paper === true) return INKS
  return COLOR
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const place = app.config.place || {}
  if (place.latitude == null) {
    throw new Error(place.error || 'No place yet')
  }
  const lat = Number(place.latitude)
  const lon = Number(place.longitude)
  const twelve = app.config.clock === '12h'
  const nowDate = new Date()
  const now = nowDate.getTime()
  const midnight = new Date(nowDate.getFullYear(), nowDate.getMonth(), nowDate.getDate()).getTime()
  const dayLength = new Date(nowDate.getFullYear(), nowDate.getMonth(), nowDate.getDate() + 1).getTime() - midnight
  const steps = Math.round(dayLength / STEP)
  const clock = (ms: number) => {
    const d = new Date(ms)
    return timeText(d.getHours(), d.getMinutes(), twelve)
  }

  const sun = series(midnight, steps, (t) => sunAltitude(t, lat, lon))
  const moon = series(midnight, steps, (t) => moonAltitude(t, lat, lon))
  const yesterday = series(midnight - 86400000, 288, (t) => sunAltitude(t, lat, lon))
  const rises = crossings(midnight, sun, -0.833)
  const sunrise = rises.find((c) => c.rising)
  const sunset = rises.find((c) => !c.rising)
  // Daylight to the minute from the crossings, not the five-minute samples.
  const lengthOf = (start: number, values: number[]) => {
    const cs = crossings(start, values, -0.833)
    if (!cs.length) return values[0] > -0.833 ? values.length * STEP : 0
    let total = 0
    let from = values[0] > -0.833 ? start : null
    for (const c of cs) {
      if (c.rising) from = c.at
      else if (from != null) {
        total += c.at - from
        from = null
      }
    }
    if (from != null) total += start + (values.length - 1) * STEP - from
    return total
  }
  const daylight = lengthOf(midnight, sun)
  const daylightYesterday = lengthOf(midnight - 86400000, yesterday)
  const golden = crossings(midnight, sun, 6).filter((c) => !c.rising).pop()
  const dark = crossings(midnight, sun, -18).find((c) => !c.rising)
  const noonIndex = sun.indexOf(Math.max(...sun))
  const noon = midnight + noonIndex * STEP
  const sunNow = sunAltitude(now, lat, lon)
  const moonNow = moonAltitude(now, lat, lon)
  const lit = moonIllumination(now)
  const full = nextPhase(now, 0.5)

  if (context.round === true) {
    return roundSky({ W, H, look: lookOf(app), place, nowDate, now, midnight, dayLength, steps, sun, moon, sunrise, sunset, sunNow, lit, full, daylight, daylightYesterday, clock })
  }

  const look = lookOf(app)
  const portrait = H > W
  const u = Math.min(W, H) / 100
  const pad = u * 5
  // No word under 13 px (a cap height of 9): a watch's, a 2.8" screen's or a
  // small e-paper's u would make them 6.
  const fs = (n: number, least = 13) => Math.max(least, n)

  // The facts under the chart: four columns where each has room for its
  // words, else two by two. A note or a label too long for its column at the
  // smallest size says less.
  const columns = !portrait && (W - pad * 2) / 4 >= Math.max(130, u * 24) ? 4 : 2
  const factW = (W - pad * 2) / columns
  const capsEm = (text: string) => {
    let em = 0
    for (const c of text) em += c === ' ' ? 0.28 : c === '·' ? 0.3 : 0.68
    return em
  }
  const labelOf = (fact: { label: string; short?: string }, room: number) => {
    const long = fact.label.toUpperCase()
    const text = fact.short && capsEm(long) * fs(u * 2.4) > room ? fact.short.toUpperCase() : long
    return { text, size: fs(Math.min(u * 2.8, room / capsEm(text))) }
  }
  const sayOf = (long: string, short: string, room: number) => {
    const text = long.length * 0.47 * fs(u * 2.9) > room ? short : long
    return { text, size: fs(Math.min(u * 2.9, room / (text.length * 0.47))) }
  }
  const changed = daylight - daylightYesterday
  const facts = [
    { label: 'Daylight', value: lengthText(daylight), note: changeText(changed), noteShort: changeText(changed).replace(' on yesterday', '') },
    {
      label: 'Sunrise · sunset',
      short: 'Rise · set',
      value: sunrise && sunset ? `${clock(sunrise.at)} · ${clock(sunset.at)}` : sun[noonIndex] > 0 ? 'Up all day' : 'Down all day',
      note: `Highest at ${clock(noon)}, ${Math.round(sun[noonIndex])}°`,
      noteShort: `Noon ${Math.round(sun[noonIndex])}°`,
    },
    {
      label: 'Golden hour',
      value: golden && sunset ? `${clock(golden.at)} – ${clock(sunset.at)}` : '—',
      note: dark ? `Fully dark from ${clock(dark.at)}` : 'Never fully dark',
      noteShort: dark ? `Dark ${clock(dark.at)}` : 'Never dark',
    },
    {
      label: 'Moon',
      value: `${moonPhaseName(lit.phase)}`,
      note: `${Math.round(lit.fraction * 100)}% lit` + (full ? ` · full ${new Date(full).getDate()} ${MONTHS[new Date(full).getMonth()].substring(0, 3)}` : ''),
      noteShort: `${Math.round(lit.fraction * 100)}% lit`,
      moon: true,
    },
  ]
  const factRows = 4 / columns
  const labelH = fs(u * 2.8)
  const valueH = fs(u * 4.6, 13)
  const noteH = fs(u * 2.9)
  // A short panel sets the facts' lines closer, so the chart keeps its room.
  const tight = H < 360
  const lead = tight ? [1.2, 1.2, 1.3, 1.5] : [1.35, 1.3, 1.45, 2.5]
  const factH = labelH * lead[0] + valueH * lead[1] + noteH * lead[2] + u * lead[3]
  const factTop = H - pad - factH * factRows

  // The header: the place and the date on the left, the time and the sun on
  // the right, the date said short or the two lines stacked where one line is
  // too narrow for both.
  const headSize = fs(u * 4.2)
  const sideSize = fs(u * 3.4)
  const side = `${clock(now)} · sun ${sunNow >= 0 ? Math.round(sunNow) + '° up' : Math.round(-sunNow) + '° down'}`
  const longDate = `${WEEKDAYS[nowDate.getDay()]} ${nowDate.getDate()} ${MONTHS[nowDate.getMonth()]}`
  const shortDate = `${WEEKDAYS[nowDate.getDay()].substring(0, 3)} ${nowDate.getDate()} ${MONTHS[nowDate.getMonth()].substring(0, 3)}`
  const sideW = side.length * sideSize * 0.5
  const titleFits = (text: string) => text.length * headSize * 0.55 + sideW + u * 4 <= W - pad * 2
  const prefix = place.name ? place.name + ' · ' : ''
  const stack = !titleFits(prefix + shortDate)
  const title = prefix + (stack || titleFits(prefix + longDate) ? longDate : shortDate)
  const headY = Math.max(u * 8, pad + headSize * 0.8)
  const sideY = stack ? headY + sideSize * 1.5 : headY

  const tickSize = fs(u * 3)
  const chartLeft = pad
  const chartRight = W - pad
  const chartTop = sideY + Math.max(u * 7, sideSize)
  const chartBottom = factTop - (tight ? u * 2.7 + tickSize * 1.4 : tickSize * 1.6 + Math.max(u * 4.4, tickSize))
  const low = -24
  const high = Math.max(20, Math.max(...sun), Math.max(...moon)) + 8
  const x = (ms: number) => chartLeft + ((ms - midnight) / dayLength) * (chartRight - chartLeft)
  const y = (alt: number) => chartBottom - ((Math.max(low, alt) - low) / (high - low)) * (chartBottom - chartTop)
  const horizonY = y(0)

  // The sky, a stop every half hour.
  const stops = []
  for (let i = 0; i <= steps; i += 6) {
    stops.push(<stop offset={(i / steps).toFixed(4)} stopColor={skyAt(sun[i])} />)
  }
  const path = (values: number[], keep: (a: number) => boolean) => {
    let d = ''
    let drawing = false
    values.forEach((a, i) => {
      if (keep(a)) {
        d += `${drawing ? 'L' : 'M'}${x(midnight + i * STEP).toFixed(1)} ${y(a).toFixed(1)} `
        drawing = true
      } else {
        drawing = false
      }
    })
    return d
  }
  // Where the sky has no color: the night hatched or one ink, the day clear.
  const hatch = []
  if (!look.sky) {
    const gap = Math.max(4, u * 2.2)
    const line = Math.max(1, u * 0.22)
    let from = -1
    for (let i = 0; i <= steps; i++) {
      const night = sun[i] < -0.833 && i < steps
      if (night && from < 0) from = i
      if (!night && from >= 0) {
        const x1 = x(midnight + from * STEP)
        const x2 = x(midnight + i * STEP)
        if (look.night) hatch.push(<rect x={x1.toFixed(1)} y={chartTop} width={(x2 - x1).toFixed(1)} height={chartBottom - chartTop} fill={look.night} />)
        else for (let c = x1 + chartTop; c < x2 + chartBottom; c += gap) {
          const xs = Math.max(x1, c - chartBottom)
          const xe = Math.min(x2, c - chartTop)
          if (xe > xs) hatch.push(<line x1={xs.toFixed(1)} y1={(c - xs).toFixed(1)} x2={xe.toFixed(1)} y2={(c - xe).toFixed(1)} stroke={look.hatch} strokeWidth={line} />)
        }
        from = -1
      }
    }
  }
  // A line or a word on the night gets the page around it. Without the sky a
  // straight line is whole pixels: a hairline's soft edge is grey, which
  // 1-bit dithers away and color e-paper makes red and blue.
  const casing = Math.max(1.5, u * 0.35)
  const hair = look.sky ? Math.max(1, u * 0.3) : Math.max(2, Math.round(u * 0.3))
  const crisp = (v: number) => (look.sky ? v : Math.round(v) + (hair % 2 ? 0.5 : 0))
  const backing = (cx: number, cy: number, text: string, size: number) =>
    look.sky ? null : <rect x={cx - text.length * size * 0.32} y={cy - size * 0.95} width={text.length * size * 0.64} height={size * 1.25} fill={look.page} />
  const ticks = []
  for (let h = 0; h <= 24; h += portrait || W < 320 ? 6 : 3) {
    const tx = x(midnight + h * 3600000)
    ticks.push(<line x1={crisp(tx)} y1={chartBottom} x2={crisp(tx)} y2={chartBottom + u * 1.2} stroke={look.axis} strokeWidth={look.sky ? Math.max(1, u * 0.25) : hair} />)
    if (h < 24 || !portrait) {
      ticks.push(
        <text x={tx} y={chartBottom + u * 1.2 + tickSize * 1.15} fontFamily="FiraGO" fontSize={tickSize} fill={look.axis} textAnchor={h === 0 ? 'start' : h === 24 ? 'end' : 'middle'}>
          {twelve ? (h % 12 || 12) + (h < 12 || h === 24 ? 'a' : 'p') : two(h % 24)}
        </text>,
      )
    }
  }
  const markSize = fs(u * 3.2)
  const marks = []
  for (const c of [sunrise, sunset]) {
    if (!c) continue
    const cx = x(c.at)
    marks.push(backing(cx, horizonY + u * 1.6 + markSize, clock(c.at), markSize))
    marks.push(<circle cx={cx} cy={horizonY} r={Math.max(2.5, u * 0.9)} fill={look.mark} />)
    marks.push(
      <text x={cx} y={horizonY + u * 1.6 + markSize} fontFamily="FiraGO" fontWeight={600} fontSize={markSize} fill={look.markText} textAnchor="middle">
        {clock(c.at)}
      </text>,
    )
  }
  const noonX = x(noon)
  const noonY = y(sun[noonIndex])
  const noonSize = fs(u * 3)
  const sunX = x(now)
  const sunY = y(sunNow)
  const moonY = y(moonNow)
  const moonR = Math.max(5, u * 2.3)
  const sunR = Math.max(5, u * 2)

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <linearGradient id="sky" gradientUnits="userSpaceOnUse" x1={chartLeft} y1="0" x2={chartRight} y2="0">
        {stops}
      </linearGradient>
      <linearGradient id="ground" gradientUnits="userSpaceOnUse" x1="0" y1={horizonY} x2="0" y2={chartBottom}>
        <stop offset="0" stopColor="#000000" stopOpacity="0.35" />
        <stop offset="1" stopColor="#000000" stopOpacity="0.6" />
      </linearGradient>
      <radialGradient id="glow" gradientUnits="userSpaceOnUse" cx={sunX} cy={sunY} r={u * 9}>
        <stop offset="0" stopColor="#ffe7a6" stopOpacity="0.7" />
        <stop offset="1" stopColor="#ffe7a6" stopOpacity="0" />
      </radialGradient>
      <rect width={W} height={H} fill={look.page} />

      <text x={pad} y={headY} fontFamily="FiraGO" fontWeight={600} fontSize={headSize} fill={look.ink}>
        {title}
      </text>
      <text x={stack ? pad : W - pad} y={sideY} fontFamily="FiraGO" fontSize={sideSize} fill={look.soft} textAnchor={stack ? 'start' : 'end'}>
        {side}
      </text>

      {look.sky ? (
        <g>
          <rect x={chartLeft} y={chartTop} width={chartRight - chartLeft} height={chartBottom - chartTop} rx={u * 1.5} fill="url(#sky)" />
          <rect x={chartLeft} y={horizonY} width={chartRight - chartLeft} height={chartBottom - horizonY} fill="url(#ground)" />
        </g>
      ) : (
        <g>
          {hatch}
          <rect x={Math.round(chartLeft)} y={Math.round(chartTop)} width={Math.round(chartRight) - Math.round(chartLeft)} height={Math.round(chartBottom) - Math.round(chartTop)} fill="none" stroke={look.ink} strokeWidth={hair} />
        </g>
      )}
      {look.sky ? null : (
        <g>
          <line x1={chartLeft} y1={crisp(horizonY)} x2={chartRight} y2={crisp(horizonY)} stroke={look.page} strokeWidth={hair + casing * 2} />
          <path d={path(moon, (a) => a > low + 0.5)} fill="none" stroke={look.page} strokeWidth={Math.max(2, u * 0.35) + casing * 2} strokeLinejoin="round" />
          <path d={path(sun, (a) => a < 0 && a > low + 0.5)} fill="none" stroke={look.page} strokeWidth={Math.max(1, u * 0.5) + casing * 2} strokeLinejoin="round" />
          <path d={path(sun, (a) => a >= -0.5)} fill="none" stroke={look.page} strokeWidth={Math.max(2, u * 0.8) + casing * 2} strokeLinecap="round" strokeLinejoin="round" />
        </g>
      )}
      <line x1={chartLeft} y1={crisp(horizonY)} x2={chartRight} y2={crisp(horizonY)} stroke={look.horizon} strokeWidth={hair} opacity={look.sky ? 0.6 : 1} />
      {look.sky ? (
        <path d={path(moon, (a) => a > low + 0.5)} fill="none" stroke={look.moonPath} strokeWidth={u * 0.35} strokeLinejoin="round" opacity={0.45} />
      ) : (
        <path d={path(moon, (a) => a > low + 0.5)} fill="none" stroke={look.moonPath} strokeWidth={Math.max(2, u * 0.35)} strokeLinejoin="round"
          strokeDasharray={`${Math.max(3, u * 1.2).toFixed(1)} ${Math.max(3, u * 1.2).toFixed(1)}`} />
      )}
      <path d={path(sun, (a) => a < 0 && a > low + 0.5)} fill="none" stroke={look.sunPath} strokeWidth={Math.max(1, u * 0.5)} strokeLinejoin="round" opacity={look.sky ? 0.35 : 1} />
      <path d={path(sun, (a) => a >= -0.5)} fill="none" stroke={look.sunPath} strokeWidth={Math.max(2, u * 0.8)} strokeLinecap="round" strokeLinejoin="round" />
      {marks}
      {sun[noonIndex] > 0 ? backing(noonX, noonY - u * 2, `${Math.round(sun[noonIndex])}°`, noonSize) : null}
      {sun[noonIndex] > 0 ? (
        <text x={noonX} y={noonY - u * 2} fontFamily="FiraGO" fontWeight={look.sky ? 400 : 600} fontSize={noonSize} fill={look.noonText} textAnchor="middle" opacity={look.sky ? 0.85 : 1}>
          {`${Math.round(sun[noonIndex])}°`}
        </text>
      ) : null}
      {look.sky ? null : <line x1={crisp(sunX)} y1={chartTop} x2={crisp(sunX)} y2={chartBottom} stroke={look.page} strokeWidth={hair + casing * 2} />}
      <line x1={crisp(sunX)} y1={chartTop} x2={crisp(sunX)} y2={chartBottom} stroke={look.now} strokeWidth={look.sky ? Math.max(1, u * 0.2) : hair} opacity={look.sky ? 0.35 : 1} />
      <circle cx={sunX} cy={moonY} r={moonR} fill={look.moonDark} stroke={look.moonRing} strokeWidth={look.sky ? 0 : Math.max(1, u * 0.3)} />
      <path d={moonPath(sunX, moonY, moonR, lit.phase)} fill={look.moonLit} />
      {look.sky ? <rect x={sunX - u * 9} y={sunY - u * 9} width={u * 18} height={u * 18} fill="url(#glow)" /> : null}
      <circle cx={sunX} cy={sunY} r={sunR} fill={look.sun} stroke={look.sunRing} strokeWidth={Math.max(1.5, u * 0.4)} />
      {ticks}

      {facts.map((fact, i) => {
        const fx = pad + (i % columns) * factW
        const fy = factTop + Math.floor(i / columns) * factH
        // The moon's disc stands left of its words, or beside its label
        // where the column is too narrow for the phase's name beside it.
        const indent = Math.max(u * 6.2, labelH * 2)
        const discUp = fact.moon && fact.value.length * 0.56 * 13 > factW - indent - u * 3
        const textX = fact.moon && !discUp ? fx + indent : fx
        const room = factW - (textX - fx) - u * 3
        const label = labelOf(fact, discUp ? room - labelH * 1.6 : room)
        const note = sayOf(fact.note, fact.noteShort, factW - (textX - fx) - u * 2)
        const labelY = fy + labelH * lead[0]
        const valueY = labelY + valueH * lead[1]
        const noteY = valueY + noteH * lead[2]
        const discR = discUp ? label.size * 0.5 : Math.min(Math.max(u * 2.6, labelH * 0.8), (textX - fx) * 0.42)
        const discX = discUp ? fx + capsEm(label.text) * label.size * 1.15 + label.size * 0.5 + discR : fx + discR + 1
        const discY = discUp ? labelY - label.size * 0.36 : (labelY + noteY) / 2 - noteH * 0.3
        return (
          <g>
            <line x1={fx} y1={crisp(fy)} x2={fx + factW - u * 3} y2={crisp(fy)} stroke={look.rule} strokeWidth={hair} />
            {fact.moon ? (
              <g>
                <circle cx={discX} cy={discY} r={discR} fill={look.moonDark} stroke={look.moonRing} strokeWidth={look.sky ? 0 : Math.max(1, u * 0.3)} />
                <path d={moonPath(discX, discY, discR, lit.phase)} fill={look.moonLit} />
              </g>
            ) : null}
            <text x={textX} y={labelY} fontFamily="FiraGO" fontWeight={600} fontSize={label.size} fill={look.label}>
              {label.text}
            </text>
            <text x={textX} y={valueY} fontFamily="FiraGO" fontWeight={600} fontSize={fs(Math.min(u * 4.6, room / (fact.value.length * 0.56)), 13)} fill={look.ink}>
              {fact.value}
            </text>
            <text x={textX} y={noteY} fontFamily="FiraGO" fontSize={note.size} fill={look.soft}>
              {note.text}
            </text>
          </g>
        )
      })}
    </svg>
  )
}

// A round panel's whole canvas: the day is a 24-hour dial, midnight at the
// bottom and noon at the top, the sky's color through the day a ring along
// the rim with the moon's hours inside it and the sun where it is now; the
// place, the time, the light and the moon in the middle.
function roundSky({ W, H, look, place, nowDate, now, midnight, dayLength, steps, sun, moon, sunrise, sunset, sunNow, lit, full, daylight, daylightYesterday, clock }) {
  const S = Math.min(W, H)
  const cx = W / 2
  const cy = H / 2
  const k = S / 466
  const outer = S / 2 - 4 * k
  const band = 30 * k
  const inner = outer - band
  const mid = (outer + inner) / 2
  const f = (n: number) => n.toFixed(1)
  // Radians from the top, clockwise: midnight at the bottom.
  const angle = (ms: number) => Math.PI + ((ms - midnight) / dayLength) * Math.PI * 2
  const at = (a: number, r: number) => [cx + Math.sin(a) * r, cy - Math.cos(a) * r]
  const segment = (a1: number, a2: number, r1: number, r2: number) => {
    const [x1, y1] = at(a1, r2)
    const [x2, y2] = at(a2, r2)
    const [x3, y3] = at(a2, r1)
    const [x4, y4] = at(a1, r1)
    const large = a2 - a1 > Math.PI ? 1 : 0
    return `M${f(x1)} ${f(y1)} A${f(r2)} ${f(r2)} 0 ${large} 1 ${f(x2)} ${f(y2)} L${f(x3)} ${f(y3)} A${f(r1)} ${f(r1)} 0 ${large} 0 ${f(x4)} ${f(y4)} Z`
  }

  // The sky, a slice every half hour.
  const slices = []
  for (let i = 0; i < steps; i += 6) {
    const a1 = angle(midnight + i * STEP)
    const a2 = angle(midnight + Math.min(steps, i + 6) * STEP) + 0.01
    const alt = sun[Math.min(steps, i + 3)]
    slices.push(<path d={segment(a1, a2, inner, outer)} fill={look.sky ? skyAt(alt) : alt < -0.833 ? look.hatch : look.page} />)
  }
  // The moon's hours above the horizon: a thin arc inside the ring.
  const moonArcs = []
  let from = -1
  for (let i = 0; i <= steps; i++) {
    const up = moon[i] > 0 && i < steps
    if (up && from < 0) from = i
    if (!up && from >= 0) {
      moonArcs.push(<path d={segment(angle(midnight + from * STEP), angle(midnight + i * STEP), inner - 9 * k, inner - 5 * k)} fill={look.moonPath} opacity={look.sky ? 0.5 : 1} />)
      from = -1
    }
  }
  const ticks = []
  for (let h = 0; h < 24; h += 3) {
    const a = angle(midnight + h * 3600000)
    const [x1, y1] = at(a, inner)
    const [x2, y2] = at(a, inner + (h % 6 === 0 ? 10 : 6) * k)
    ticks.push(<line x1={f(x1)} y1={f(y1)} x2={f(x2)} y2={f(y2)} stroke={look.axis} strokeWidth={2 * k} opacity={look.sky ? 0.6 : 1} />)
  }
  // Sunrise and sunset: a mark across the ring, the time just inside it.
  const marks = []
  for (const c of [sunrise, sunset]) {
    if (!c) continue
    const a = angle(c.at)
    const [x1, y1] = at(a, inner - 2 * k)
    const [x2, y2] = at(a, outer)
    const [tx, ty] = at(a, inner - 30 * k)
    marks.push(<line x1={f(x1)} y1={f(y1)} x2={f(x2)} y2={f(y2)} stroke={look.mark} strokeWidth={2.5 * k} />)
    marks.push(
      <text x={f(tx)} y={f(ty + 5 * k)} fontFamily="FiraGO" fontWeight={600} fontSize={f(15 * k)} fill={look.sky ? '#ffd36b' : look.ink} textAnchor="middle">
        {clock(c.at)}
      </text>,
    )
  }
  const nowA = angle(now)
  const [sx, sy] = at(nowA, mid)
  const [nx1, ny1] = at(nowA, inner - 12 * k)
  const sunUp = sunNow >= 0
  const moonR = 13 * k
  const moonY = cy + 112 * k
  const moonText = `${moonPhaseName(lit.phase)} · ${Math.round(lit.fraction * 100)}%`
  const title = place.name || `${WEEKDAYS[nowDate.getDay()]}`
  const date = (place.name ? WEEKDAYS[nowDate.getDay()] + ' ' : '') + `${nowDate.getDate()} ${MONTHS[nowDate.getMonth()]}`
  const fit = (text: string, size: number, width: number) => Math.min(size, width / (text.length * 0.56))

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <radialGradient id="glow" gradientUnits="userSpaceOnUse" cx={f(sx)} cy={f(sy)} r={f(34 * k)}>
        <stop offset="0" stopColor="#ffe7a6" stopOpacity="0.8" />
        <stop offset="1" stopColor="#ffe7a6" stopOpacity="0" />
      </radialGradient>
      <rect width={W} height={H} fill={look.page} />
      {slices}
      <circle cx={f(cx)} cy={f(cy)} r={f(inner)} fill="none" stroke={look.rule} strokeWidth={f(1.5 * k)} />
      <circle cx={f(cx)} cy={f(cy)} r={f(outer)} fill="none" stroke={look.rule} strokeWidth={f(1.5 * k)} />
      {ticks}
      {moonArcs}
      {marks}
      <line x1={f(nx1)} y1={f(ny1)} x2={f(sx)} y2={f(sy)} stroke={look.now} strokeWidth={1.5 * k} opacity={look.sky ? 0.5 : 1} />
      {sunUp && look.sky ? <rect x={f(sx - 34 * k)} y={f(sy - 34 * k)} width={f(68 * k)} height={f(68 * k)} fill="url(#glow)" /> : null}
      <circle cx={f(sx)} cy={f(sy)} r={f(10 * k)} fill={look.sky ? (sunUp ? '#ffdf85' : '#3a4262') : sunUp ? look.sun : look.page} stroke={look.sky ? (sunUp ? '#fff3cc' : '#ffd36b') : look.sunRing} strokeWidth={f(2 * k)} />

      <text x={f(cx)} y={f(cy - 98 * k)} fontFamily="FiraGO" fontWeight={600} fontSize={f(fit(title, 19 * k, 220 * k))} fill={look.ink} textAnchor="middle">
        {title}
      </text>
      <text x={f(cx)} y={f(cy - 74 * k)} fontFamily="FiraGO" fontSize={f(15 * k)} fill={look.soft} textAnchor="middle">
        {date}
      </text>
      <text x={f(cx)} y={f(cy + 8 * k)} fontFamily="FiraGO" fontWeight={600} fontSize={f(fit(clock(now), 56 * k, 230 * k))} fill={look.ink} textAnchor="middle">
        {clock(now)}
      </text>
      <text x={f(cx)} y={f(cy + 36 * k)} fontFamily="FiraGO" fontSize={f(15 * k)} fill={look.soft} textAnchor="middle">
        {`sun ${sunUp ? Math.round(sunNow) + '° up' : Math.round(-sunNow) + '° down'}`}
      </text>
      <text x={f(cx)} y={f(cy + 72 * k)} fontFamily="FiraGO" fontWeight={600} fontSize={f(17 * k)} fill={look.ink} textAnchor="middle">
        {`${lengthText(daylight)} of daylight`}
      </text>
      <text x={f(cx)} y={f(cy + 90 * k)} fontFamily="FiraGO" fontSize={f(14 * k)} fill={look.soft} textAnchor="middle">
        {changeText(daylight - daylightYesterday)}
      </text>
      <circle cx={f(cx)} cy={f(moonY + 12 * k)} r={f(moonR)} fill={look.moonDark} stroke={look.moonRing} strokeWidth={look.sky ? 0 : f(1.5 * k)} />
      <path d={moonPath(cx, moonY + 12 * k, moonR, lit.phase)} fill={look.moonLit} />
      <text x={f(cx)} y={f(moonY + 44 * k)} fontFamily="FiraGO" fontSize={f(fit(moonText, 14 * k, 200 * k))} fill={look.soft} textAnchor="middle">
        {moonText}
      </text>
    </svg>
  )
}

